local item_lib = require("items")

function event_say(e)
  if e.message:findi("hail") then
    e.self:Say("I seek those who practice the art of dark magicks. I seek those who call themselves necromancers. Are you a necromancer?")
  end
  if e.message:findi("i am a necromancer") then
    e.self:Say("Excellent. Are you sure enough of your skills to undertake my tasks? If not, get out of my sight, weakling!")
  end
  if e.message:findi("undertake your tasks") then
    e.self:Say("I thought so. One should never back down from a challenge. Once you have completed them, I will have a cap, a robe, sleeves, wristbands, gloves, leggings and boots to reward you with.")
  end
  if e.message:findi("cap") then
    e.self:Say("For an enchanted head guard bring me a torn enchanted silk turban as well as three pieces of crushed flame opal.")
  end
  if e.message:findi("robe") then
    e.self:Say("If you wish to have a fine robe, bring unto me a torn enchanted silk robe and three pristine emeralds. Then you will receive a robe beyond your wildest dreams.")
  end
  if e.message:findi("sleeves") then
    e.self:Say("Bring unto me a set of torn enchanted silk sleeves as well as three flawed topaz. With these in my possession I can create a set of enchanted sleeves the likes of which spellcasters like you dream of.")
  end
  if e.message:findi("wristbands") then
    e.self:Say("A torn enchanted silk wristband and three crushed onyx sapphires is all that I require to create an imbued wrist wrap of great power. Seek out these items and return to me when you have acquired them.")
  end
  if e.message:findi("leggings") then
    e.self:Say("Three nephrite and a pair of torn enchanted silk pantaloons will net you a fine set of pantaloons.")
  end
  if e.message:findi("boots") then
    e.self:Say("Three crushed jaundice gems combined with torn enchanted silk boots would make a most interesting set of footwear. The latent powers of the gems can be harnessed to create magical effects.")
  end
  if e.message:findi("gloves") then
    e.self:Say("If you seek gloves of great power, bring to me three crushed topaz and a pair of torn enchanted silk gloves. I will use the power of the gems to imbue the gloves.")
  end
end

